-- Blocco 4: catalogo prodotti per ricerca e calcolo tramite tool server-side.
create table public.product_catalog (
  id text primary key check (id ~ '^P[0-9]{3}$'),
  name text not null check (length(trim(name)) between 1 and 120),
  category text not null check (length(trim(category)) between 1 and 60),
  min_dimensions jsonb not null,
  max_dimensions jsonb not null,
  allowed_woods jsonb not null,
  delivery_days integer not null check (delivery_days between 1 and 365),
  typical_dimensions jsonb not null,
  description text not null check (length(description) <= 300),
  active boolean not null default true
);
alter table public.product_catalog enable row level security;
revoke all on public.product_catalog from anon, authenticated;
grant select on public.product_catalog to anon, authenticated;
create policy "Read active product catalog" on public.product_catalog for select to anon, authenticated using (active);
on conflict (id) do update set name=excluded.name,category=excluded.category,min_dimensions=excluded.min_dimensions,max_dimensions=excluded.max_dimensions,allowed_woods=excluded.allowed_woods,delivery_days=excluded.delivery_days,typical_dimensions=excluded.typical_dimensions,description=excluded.description;
